<script setup lang="ts">
import { computed, ref } from 'vue';import {useI18n}from'vue-i18n';import{getTool}from'../registry';import{defang,refang}from'./defang'
const{t}=useI18n();const tool=getTool('soc-tools.defang');const input=ref('');const output=ref('');const mode=ref<'defang'|'refang'>('defang');const copied=ref(false);const inputBytes=computed(()=>new TextEncoder().encode(input.value).byteLength);const isOverLimit=computed(()=>inputBytes.value>tool.recommendedMaxInputBytes);function transform(){copied.value=false;output.value=input.value?(mode.value==='defang'?defang(input.value):refang(input.value)):''}function clear(){input.value='';output.value='';copied.value=false}async function copyOutput(){if(output.value){await navigator.clipboard.writeText(output.value);copied.value=true}}
</script>
<template><section class="tool-page" aria-labelledby="tool-title"><header class="tool-heading"><span class="category">{{ t(`categories.${tool.category}`) }}</span><h1 id="tool-title">{{ t(tool.nameKey) }}</h1><p>{{ t(tool.descriptionKey) }}</p></header><div class="io-panel"><div class="terminal-titlebar"><span class="window-marks" aria-hidden="true"><i /><i /><i /></span><span>[ defang ]</span></div><div class="io-strip"><fieldset><legend>{{ t('common.operation') }}</legend><label class="radio-control"><input v-model="mode" type="radio" value="defang" @change="transform"><span>{{ t('tools.defang.defang') }}</span></label><label class="radio-control"><input v-model="mode" type="radio" value="refang" @change="transform"><span>{{ t('tools.defang.refang') }}</span></label></fieldset><span class="byte-count">{{ inputBytes }} B</span><div class="strip-actions"><button class="icon-button" type="button" :disabled="!output" :aria-label="copied?t('common.copied'):t('common.copy')" @click="copyOutput"><svg aria-hidden="true" viewBox="0 0 24 24"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M15 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h3" /></svg></button><button class="icon-button" type="button" :aria-label="t('common.clear')" @click="clear"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14" /></svg></button></div></div><p class="notice" role="note">{{ t('tools.defang.limitation') }}</p><p v-if="isOverLimit" class="notice warning" role="status">{{ t('common.warning',{size:'1 MB'}) }}</p><div class="editor-grid"><div class="field"><label for="defang-input"><span>$</span> {{ t('common.input') }}</label><div class="terminal-editor input-editor"><span class="editor-prompt" aria-hidden="true">$</span><textarea id="defang-input" v-model="input" :placeholder="t('tools.defang.placeholder')" spellcheck="false" @input="transform" /></div></div><div class="field"><label for="defang-output"><span>&gt;</span> {{ t('common.output') }}</label><div class="terminal-editor"><span class="editor-prompt" aria-hidden="true">&gt;</span><textarea id="defang-output" :value="output" :placeholder="t('common.result')" readonly /></div></div></div></div></section></template>
